/**
 * Evaluates flag `flag` for `ctx`: disabled → the default; else the first rule
 * whose conditions hold and whose percentage admits the subject; else the
 * default.
 */
export function evaluate(
	flag: string,
	spec: ConfigFlagSpec,
	ctx: FlagContext,
	segments: ReadonlyMap<string, ConfigSegmentSpec> = new Map(),
): FlagEvaluation {
	const fallback = (reason: EvaluationReason): FlagEvaluation => ({ value: spec.defaultValue ?? null, reason })
	if (spec.enabled === false) return fallback('disabled')
	const rules: TargetingRule[] = spec.rules ?? []
	for (const [i, rule] of rules.entries()) {
		if (!(rule.conditions ?? []).every((c) => holds(c, ctx, segments))) continue
		const percentage = rule.percentage ?? 100
		if (percentage >= 100) return { value: rule.value ?? null, reason: 'targeting_match', ruleIndex: i }
		const subject = subjectOf(rule.bucketAttribute, ctx)
		if (subject === undefined || percentage <= 0) continue
		if (bucket(flag, subject) < percentage) return { value: rule.value ?? null, reason: 'split', ruleIndex: i }
	}
	return fallback('default')
}

