function durationMs(d: string | undefined, fallback: number): number {
	const m = d ? /^(\d+(?:\.\d+)?)s$/.exec(d) : null
	return m ? Number(m[1]) * 1000 : fallback
}

const idOf = (name: string | undefined): string => (name ?? '').slice((name ?? '').lastIndexOf('/') + 1)

const NOT_FOUND: FlagEvaluation = { value: null, reason: 'not_found' }

/** Evaluates an environment's flags, locally or through the API. */
export class Flags {
	readonly mode: 'local' | 'remote'
	private readonly client: Sylphx
	private readonly parent: string
	private readonly ttl: number
	private readonly now: () => number
	private ruleset: Ruleset | undefined
	private refreshing: Promise<Ruleset> | undefined
	private readonly cache = new Map<string, { at: number; values: Map<string, FlagEvaluation> }>()

	constructor(options: FlagsOptions) {
		this.client = options.client
		this.parent = options.parent
		this.mode = options.mode ?? 'remote'
		this.ttl = options.cacheTtlMs ?? 5 * 60 * 1000
		this.now = options.now ?? Date.now
	}

	/** Whether a boolean flag is on for `ctx`; false when it is missing. */
	async isEnabled(flag: string, ctx: FlagContext = {}): Promise<boolean> {
		return (await this.evaluate(flag, ctx)).value === true
	}

	/** A flag's value for `ctx`, or `fallback` when the flag is missing. */
	async getValue<T>(flag: string, ctx: FlagContext, fallback: T): Promise<T> {
		const e = await this.evaluate(flag, ctx)
		return e.reason === 'not_found' || e.value === null || e.value === undefined ? fallback : (e.value as T)
	}

	/** A flag's evaluation for `ctx`. */
	async evaluate(flag: string, ctx: FlagContext = {}): Promise<FlagEvaluation> {
		if (this.mode === 'local') {
			const r = await this.current()
			const spec = r.flags.get(flag)
			return spec ? evaluate(flag, spec, ctx, r.segments) : NOT_FOUND
		}
		return (await this.evaluateAll(ctx)).get(flag) ?? NOT_FOUND
	}

	/** Every flag's evaluation for `ctx`, by id. */
	async evaluateAll(ctx: FlagContext = {}): Promise<Map<string, FlagEvaluation>> {
		if (this.mode === 'local') {
			const r = await this.current()
			return new Map([...r.flags].map(([id, spec]) => [id, evaluate(id, spec, ctx, r.segments)]))
		}
		const key = JSON.stringify([ctx.userId ?? '', ctx.anonymousId ?? '', ctx.attributes ?? {}])
		const hit = this.cache.get(key)
		if (hit && this.now() - hit.at < this.ttl) return hit.values
		const res = await this.client.config.configFlags.evaluate({
			parent: this.parent,
			context: {
				...(ctx.userId ? { userId: ctx.userId } : {}),
				...(ctx.anonymousId ? { anonymousId: ctx.anonymousId } : {}),
				...(ctx.attributes ? { attributes: ctx.attributes } : {}),
			},
		})
		const values = new Map<string, FlagEvaluation>()
		for (const e of res.evaluations ?? []) {
			values.set(e.configFlag ?? '', {
				value: e.value ?? null,
				reason: e.reason ?? 'default',
				...(e.ruleIndex !== undefined ? { ruleIndex: e.ruleIndex } : {}),
			})
		}
		if (this.cache.size > 1000) this.cache.clear()
		this.cache.set(key, { at: this.now(), values })
		return values
	}

	/** Forgets cached answers and the ruleset; the next call fetches. */
	reset(): void {
		this.cache.clear()
		this.ruleset = undefined
	}

	/** The ruleset, polled with its etag once its poll interval has passed. */
	private async current(): Promise<Ruleset> {
		const r = this.ruleset
		if (r && this.now() - r.fetchedAt < r.pollMs) return r
		this.refreshing ??= this.fetchRuleset(r).finally(() => {
			this.refreshing = undefined
		})
		try {
			return await this.refreshing
		} catch (error) {
			// A Cell keeps its last good ruleset while the API is away.
			if (r) return r
			throw error
		}
	}

	private async fetchRuleset(held: Ruleset | undefined): Promise<Ruleset> {
		const snap = await this.client.config.configFlags.snapshot({
			parent: this.parent,
			...(held ? { ifNoneMatch: held.etag } : {}),
		})
		const pollMs = durationMs(snap.pollInterval, 30_000)
		if (held && snap.notModified) {
			this.ruleset = { ...held, fetchedAt: this.now(), pollMs }
			return this.ruleset
		}
		const flags = new Map<string, ConfigFlagSpec>()
		for (const f of snap.configFlags ?? []) if (f.spec) flags.set(idOf(f.name), f.spec)
		const segments = new Map<string, ConfigSegmentSpec>()
		for (const s of snap.configSegments ?? []) if (s.spec) segments.set(idOf(s.name), s.spec)
		this.ruleset = { etag: snap.etag ?? '', flags, segments, fetchedAt: this.now(), pollMs }
		return this.ruleset
	}
}

