/** OpenFeature's evaluation context: `targetingKey` is the subject. */
export interface OpenFeatureContext {
	targetingKey?: string
	[key: string]: unknown
}

/** OpenFeature's resolution details. */
export interface ResolutionDetails<T> {
	value: T
	reason?: string
	variant?: string
	errorCode?: 'FLAG_NOT_FOUND' | 'TYPE_MISMATCH' | 'GENERAL'
	errorMessage?: string
}

type Kind = 'boolean' | 'string' | 'number' | 'object'

/** OpenFeature context → a flag context: `targetingKey` is the user. */
export function fromOpenFeature(context: OpenFeatureContext = {}): FlagContext {
	const { targetingKey, anonymousId, ...attributes } = context
	return {
		...(typeof targetingKey === 'string' && targetingKey ? { userId: targetingKey } : {}),
		...(typeof anonymousId === 'string' && anonymousId ? { anonymousId } : {}),
		attributes,
	}
}

const REASONS: Record<string, string> = {
	targeting_match: 'TARGETING_MATCH',
	split: 'SPLIT',
	default: 'DEFAULT',
	disabled: 'DISABLED',
}

function resolve<T>(e: FlagEvaluation, kind: Kind, fallback: T): ResolutionDetails<T> {
	if (e.reason === 'not_found') {
		return { value: fallback, reason: 'ERROR', errorCode: 'FLAG_NOT_FOUND', errorMessage: 'No flag has this id.' }
	}
	const v = e.value
	const fits =
		kind === 'object' ? v !== null && typeof v === 'object' : typeof v === kind
	if (!fits) {
		return {
			value: fallback,
			reason: 'ERROR',
			errorCode: 'TYPE_MISMATCH',
			errorMessage: `The flag's value is not a ${kind}.`,
		}
	}
	return {
		value: v as T,
		reason: REASONS[e.reason] ?? 'UNKNOWN',
		...(e.ruleIndex !== undefined ? { variant: `rule-${e.ruleIndex}` } : {}),
	}
}

/** An OpenFeature server provider (`OpenFeature.setProvider(new SylphxServerProvider(flags))`). */
export class SylphxServerProvider {
	readonly metadata = { name: 'sylphx' } as const
	readonly runsOn = 'server' as const
	constructor(readonly flags: Flags) {}

	private async run<T>(flag: string, kind: Kind, fallback: T, context?: OpenFeatureContext) {
		try {
			return resolve(await this.flags.evaluate(flag, fromOpenFeature(context)), kind, fallback)
		} catch (error) {
			return { value: fallback, reason: 'ERROR', errorCode: 'GENERAL', errorMessage: String(error) } as ResolutionDetails<T>
		}
	}
	resolveBooleanEvaluation(flag: string, fallback: boolean, context?: OpenFeatureContext) {
		return this.run(flag, 'boolean', fallback, context)
	}
	resolveStringEvaluation(flag: string, fallback: string, context?: OpenFeatureContext) {
		return this.run(flag, 'string', fallback, context)
	}
	resolveNumberEvaluation(flag: string, fallback: number, context?: OpenFeatureContext) {
		return this.run(flag, 'number', fallback, context)
	}
	resolveObjectEvaluation<T>(flag: string, fallback: T, context?: OpenFeatureContext) {
		return this.run(flag, 'object', fallback, context)
	}
}

/**
 * An OpenFeature web provider: one `:evaluate` per context (on `initialize`
 * and `onContextChange`), then synchronous answers, as the web SDK requires.
 */
export class SylphxWebProvider {
	readonly metadata = { name: 'sylphx' } as const
	readonly runsOn = 'client' as const
	private values = new Map<string, FlagEvaluation>()
	constructor(readonly flags: Flags) {}

	async initialize(context?: OpenFeatureContext): Promise<void> {
		this.values = await this.flags.evaluateAll(fromOpenFeature(context))
	}
	async onContextChange(_old: OpenFeatureContext, next: OpenFeatureContext): Promise<void> {
		await this.initialize(next)
	}
	private run<T>(flag: string, kind: Kind, fallback: T): ResolutionDetails<T> {
		return resolve(this.values.get(flag) ?? NOT_FOUND, kind, fallback)
	}
	resolveBooleanEvaluation(flag: string, fallback: boolean) {
		return this.run(flag, 'boolean', fallback)
	}
	resolveStringEvaluation(flag: string, fallback: string) {
		return this.run(flag, 'string', fallback)
	}
	resolveNumberEvaluation(flag: string, fallback: number) {
		return this.run(flag, 'number', fallback)
	}
	resolveObjectEvaluation<T>(flag: string, fallback: T) {
		return this.run(flag, 'object', fallback)
	}
}
